import {
  cookieAdapter
} from "./chunk-RKSRCRNS.js";
import {
  hasLocalStorage,
  hasSessionStorage,
  hasWindowEvents
} from "./chunk-6UN7OF6Y.js";

// src/adapters/local.ts
var localAdapter = ({ key, onStorageError }) => ({
  get() {
    if (!hasLocalStorage()) return null;
    try {
      return globalThis.localStorage.getItem(key);
    } catch (error) {
      onStorageError?.(error, { operation: "get", key });
      return null;
    }
  },
  set(value) {
    if (!hasLocalStorage()) return;
    try {
      globalThis.localStorage.setItem(key, value);
    } catch (error) {
      onStorageError?.(error, { operation: "set", key });
    }
  },
  subscribe(cb) {
    if (!hasWindowEvents()) return () => {
    };
    const handler = (e) => {
      if (e.key && e.key !== key) return;
      cb(e.newValue);
    };
    try {
      window.addEventListener("storage", handler);
      return () => window.removeEventListener("storage", handler);
    } catch (_e) {
      return () => {
      };
    }
  }
});

// src/adapters/hybrid.ts
var hybridAdapter = (opts) => {
  const { onStorageError } = opts;
  const cookie = cookieAdapter(opts);
  const local = localAdapter(opts);
  return {
    get() {
      const c = cookie.get();
      if (c !== null) return c;
      const l = local.get();
      if (l !== null) {
        try {
          cookie.set(l);
        } catch (error) {
          onStorageError?.(error, { operation: "set", key: opts.cookie.name });
        }
      }
      return l;
    },
    set(value) {
      try {
        cookie.set(value);
      } catch (error) {
        onStorageError?.(error, { operation: "set", key: opts.cookie.name });
      }
      try {
        local.set(value);
      } catch (error) {
        onStorageError?.(error, { operation: "set", key: opts.key });
      }
    },
    subscribe(cb) {
      return local.subscribe ? local.subscribe(cb) : () => {
      };
    }
  };
};

// src/adapters/session.ts
var sessionAdapter = ({ key, onStorageError }) => ({
  get() {
    if (!hasSessionStorage()) return null;
    try {
      return globalThis.sessionStorage.getItem(key);
    } catch (error) {
      onStorageError?.(error, { operation: "get", key });
      return null;
    }
  },
  set(value) {
    if (!hasSessionStorage()) return;
    try {
      globalThis.sessionStorage.setItem(key, value);
    } catch (error) {
      onStorageError?.(error, { operation: "set", key });
    }
  }
});

// src/adapters/index.ts
function resolveAdapter(opts) {
  if (opts.mode === "none") {
    return { get: () => null, set: () => {
    } };
  }
  const adapterOpts = {
    key: opts.key,
    cookie: {
      name: opts.cookieOptions?.name ?? opts.key,
      maxAge: opts.cookieOptions?.maxAge,
      path: opts.cookieOptions?.path,
      domain: opts.cookieOptions?.domain,
      sameSite: opts.cookieOptions?.sameSite,
      secure: opts.cookieOptions?.secure
    },
    onStorageError: opts.onStorageError
  };
  switch (opts.mode) {
    case "cookie":
      return cookieAdapter(adapterOpts);
    case "hybrid":
      return hybridAdapter(adapterOpts);
    case "local":
      return localAdapter(adapterOpts);
    case "session":
      return sessionAdapter(adapterOpts);
  }
}

export {
  localAdapter,
  hybridAdapter,
  sessionAdapter,
  resolveAdapter
};
